#include <iostream>
using namespace std;

int main() {
    // Lettura dati di input
    float cateto_a, cateto_b, ipotenusa;

    cout << "Inserire il primo cateto di un triangolo: ";
    cin >> cateto_a;

    cout << "Inserire il secondo cateto di un triangolo: ";
    cin >> cateto_b;

    cout << "Inserire l'ipotenusa di un triangolo: ";
    cin >> ipotenusa;

    // Logica del programma
    if (cateto_a == cateto_b && cateto_b == ipotenusa)
        cout << "Il triangolo è equilatero" << endl;
    else if (cateto_a == cateto_b || cateto_a == ipotenusa || cateto_b == ipotenusa)
        cout << "Il triangolo è isoscele" << endl;
    else
        cout << "Il triangolo è scaleno" << endl;

    system("pause");
}
